CREATE TABLE app_meta ( id INTEGER NOT NULL PRIMARY KEY CHECK (id = 1), schema_version INTEGER NOT NULL, clinical_dataset_version INTEGER NOT NULL, last_export_at INTEGER );
CREATE TABLE body_change_entry ( id TEXT NOT NULL PRIMARY KEY, change_type_id TEXT NOT NULL REFERENCES body_change_type(id), observed_at INTEGER NOT NULL, observed_at_offset_seconds INTEGER NOT NULL, intensity INTEGER CHECK (intensity IS NULL OR intensity BETWEEN 0 AND 4), measurement_value REAL, measurement_unit TEXT, notes TEXT, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, deleted_at INTEGER );
CREATE TABLE body_change_type ( id TEXT NOT NULL PRIMARY KEY, code TEXT NOT NULL UNIQUE, label_key TEXT, custom_label TEXT, category TEXT NOT NULL, is_reversible INTEGER CHECK (is_reversible IS NULL OR is_reversible IN (0, 1)), supports_measurement INTEGER NOT NULL CHECK (supports_measurement IN (0, 1)), measurement_unit TEXT, is_builtin INTEGER NOT NULL CHECK (is_builtin IN (0, 1)), is_hidden INTEGER NOT NULL CHECK (is_hidden IN (0, 1)), created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, deleted_at INTEGER, CHECK ((is_builtin = 1 AND label_key IS NOT NULL) OR (is_builtin = 0 AND custom_label IS NOT NULL)) );
CREATE TABLE calendar_event ( id TEXT NOT NULL PRIMARY KEY, title TEXT NOT NULL, description TEXT, start_at INTEGER NOT NULL, start_at_offset_seconds INTEGER NOT NULL, end_at INTEGER, end_at_offset_seconds INTEGER, is_all_day INTEGER NOT NULL CHECK (is_all_day IN (0, 1)), category TEXT NOT NULL, source_type TEXT NOT NULL, source_id TEXT, reminder_minutes_before INTEGER CHECK (reminder_minutes_before IS NULL OR reminder_minutes_before >= 0), recurrence_rule TEXT, completed_at INTEGER, completed_at_offset_seconds INTEGER, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, deleted_at INTEGER, CHECK ((end_at IS NULL) = (end_at_offset_seconds IS NULL)), CHECK ((completed_at IS NULL) = (completed_at_offset_seconds IS NULL)), CHECK (end_at IS NULL OR end_at >= start_at) );
CREATE TABLE dose_log ( id TEXT NOT NULL PRIMARY KEY, regimen_id TEXT REFERENCES regimen(id) ON DELETE SET NULL, medication_id TEXT NOT NULL REFERENCES medication(id), dose_value REAL NOT NULL CHECK (dose_value > 0), dose_unit TEXT NOT NULL, route TEXT NOT NULL, injection_site TEXT, taken_at INTEGER NOT NULL, taken_at_offset_seconds INTEGER NOT NULL, notes TEXT, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, deleted_at INTEGER );
CREATE TABLE exercise_session ( id TEXT NOT NULL PRIMARY KEY, activity TEXT NOT NULL, duration_minutes INTEGER NOT NULL CHECK (duration_minutes > 0), intensity TEXT NOT NULL, occurred_at INTEGER NOT NULL, occurred_at_offset_seconds INTEGER NOT NULL, notes TEXT, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, deleted_at INTEGER );
CREATE TABLE expected_change ( id TEXT NOT NULL PRIMARY KEY, change_type_code TEXT NOT NULL, protocol TEXT NOT NULL, onset_months_min REAL NOT NULL, onset_months_max REAL, max_effect_months_min REAL, max_effect_months_max REAL, permanence TEXT NOT NULL, permanence_source_key TEXT, source_key TEXT NOT NULL, dataset_version INTEGER NOT NULL, UNIQUE (change_type_code, protocol, source_key), CHECK (onset_months_max IS NULL OR onset_months_max >= onset_months_min), CHECK (max_effect_months_min IS NULL OR max_effect_months_max IS NULL OR max_effect_months_max >= max_effect_months_min) );
CREATE TABLE health_condition ( id TEXT NOT NULL PRIMARY KEY, label TEXT NOT NULL, code TEXT, severity TEXT NOT NULL, status TEXT NOT NULL, diagnosed_at INTEGER, resolved_at INTEGER, affects_treatment INTEGER NOT NULL CHECK (affects_treatment IN (0, 1)), notes TEXT, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, deleted_at INTEGER, CHECK (diagnosed_at IS NULL OR resolved_at IS NULL OR resolved_at >= diagnosed_at) );
CREATE TABLE lab_analyte ( id TEXT NOT NULL PRIMARY KEY, code TEXT NOT NULL UNIQUE, label_key TEXT, custom_label TEXT, default_unit TEXT NOT NULL, is_builtin INTEGER NOT NULL CHECK (is_builtin IN (0, 1)), is_hidden INTEGER NOT NULL CHECK (is_hidden IN (0, 1)), created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, deleted_at INTEGER, CHECK ((is_builtin = 1 AND label_key IS NOT NULL) OR (is_builtin = 0 AND custom_label IS NOT NULL)) );
CREATE TABLE lab_result ( id TEXT NOT NULL PRIMARY KEY, analyte_id TEXT NOT NULL REFERENCES lab_analyte(id), value REAL NOT NULL, unit TEXT NOT NULL, collected_at INTEGER NOT NULL, collected_at_offset_seconds INTEGER NOT NULL, reference_low REAL, reference_high REAL, lab_name TEXT, notes TEXT, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, deleted_at INTEGER, CHECK (reference_low IS NULL OR reference_high IS NULL OR reference_low <= reference_high) );
CREATE TABLE measurement ( id TEXT NOT NULL PRIMARY KEY, type TEXT NOT NULL, custom_label TEXT, value REAL NOT NULL, unit TEXT NOT NULL, measured_at INTEGER NOT NULL, measured_at_offset_seconds INTEGER NOT NULL, notes TEXT, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, deleted_at INTEGER, CHECK (type <> 'CUSTOM' OR custom_label IS NOT NULL) );
CREATE TABLE media_attachment ( id TEXT NOT NULL PRIMARY KEY, owner_type TEXT NOT NULL, owner_id TEXT NOT NULL, relative_path TEXT NOT NULL UNIQUE, mime_type TEXT NOT NULL, captured_at INTEGER, captured_at_offset_seconds INTEGER, checksum_sha256 TEXT NOT NULL, caption TEXT, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, deleted_at INTEGER, CHECK ((captured_at IS NULL) = (captured_at_offset_seconds IS NULL)) );
CREATE TABLE medication ( id TEXT NOT NULL PRIMARY KEY, name TEXT NOT NULL, substance TEXT, default_route TEXT, concentration_value REAL CHECK (concentration_value IS NULL OR concentration_value > 0), concentration_unit TEXT, is_builtin INTEGER NOT NULL CHECK (is_builtin IN (0, 1)), is_hidden INTEGER NOT NULL CHECK (is_hidden IN (0, 1)), created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, deleted_at INTEGER, CHECK ((concentration_value IS NULL) = (concentration_unit IS NULL)) );
CREATE TABLE mood_log ( id TEXT NOT NULL PRIMARY KEY, entry_date INTEGER NOT NULL UNIQUE, mood INTEGER NOT NULL CHECK (mood BETWEEN 1 AND 5), energy INTEGER NOT NULL CHECK (energy BETWEEN 1 AND 5), anxiety INTEGER CHECK (anxiety IS NULL OR anxiety BETWEEN 1 AND 5), dysphoria INTEGER CHECK (dysphoria IS NULL OR dysphoria BETWEEN 1 AND 5), sleep_hours REAL CHECK (sleep_hours IS NULL OR sleep_hours BETWEEN 0 AND 24), note TEXT, tags TEXT NOT NULL, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, deleted_at INTEGER, relief INTEGER CHECK (relief IS NULL OR relief BETWEEN 1 AND 5), irritability INTEGER CHECK (irritability IS NULL OR irritability BETWEEN 1 AND 5), emotional_intensity INTEGER CHECK (emotional_intensity IS NULL OR emotional_intensity BETWEEN 1 AND 5) );
CREATE TABLE profile ( id TEXT NOT NULL PRIMARY KEY CHECK (id = 'default'), display_name TEXT, height_cm REAL CHECK (height_cm IS NULL OR height_cm > 0), birth_year INTEGER, treatment_protocol TEXT NOT NULL, hrt_start_date INTEGER, locale TEXT, unit_system TEXT NOT NULL, show_bmi INTEGER NOT NULL CHECK (show_bmi IN (0, 1)), body_vocabulary TEXT NOT NULL, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, deleted_at INTEGER );
CREATE TABLE regimen ( id TEXT NOT NULL PRIMARY KEY, medication_id TEXT NOT NULL REFERENCES medication(id), dose_value REAL NOT NULL CHECK (dose_value > 0), dose_unit TEXT NOT NULL, route TEXT NOT NULL, schedule_type TEXT NOT NULL, schedule_config TEXT NOT NULL, time_of_day INTEGER CHECK (time_of_day IS NULL OR time_of_day BETWEEN 0 AND 1439), start_date INTEGER NOT NULL, end_date INTEGER, is_active INTEGER NOT NULL CHECK (is_active IN (0, 1)), notes TEXT, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, deleted_at INTEGER, CHECK (end_date IS NULL OR end_date >= start_date) );
CREATE INDEX body_change_entry_type_observed ON body_change_entry(change_type_id, observed_at);
CREATE INDEX calendar_event_start_at ON calendar_event(start_at);
CREATE INDEX dose_log_taken_at ON dose_log(taken_at);
CREATE INDEX exercise_session_occurred ON exercise_session(occurred_at);
CREATE INDEX lab_result_analyte_collected ON lab_result(analyte_id, collected_at);
CREATE INDEX measurement_type_measured ON measurement(type, measured_at);
CREATE INDEX media_attachment_owner ON media_attachment(owner_type, owner_id);
